"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["55754"],{17240(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.ato_do_processo.ato_corrigido_eh_item_do_edital","status":422,"titulo":"O ato corrigido \xe9 um item do edital e s\xf3 se corrige pela publica\xe7\xe3o do item"},"descricao":{"codigo":"uniplus.selecao.ato_do_processo.ato_corrigido_eh_item_do_edital","requisitos":["UNI-REQ-0156","UNI-REQ-0157"],"oQueAconteceu":["O documento avulso indica, como ato corrigido, a publica\xe7\xe3o de um item que o edital declara,\\ncomo um resultado, ou uma corre\xe7\xe3o dessa publica\xe7\xe3o na mesma cadeia. A corre\xe7\xe3o de um item do\\nedital passa pela publica\xe7\xe3o do pr\xf3prio item, porque \xe9 ali que o sistema confirma a pol\xedtica\\nde divulga\xe7\xe3o do certame e aplica as travas do ciclo de recurso, como a de n\xe3o corrigir o\\npreliminar depois do definitivo. O documento avulso n\xe3o passa por essas confer\xeancias, e por\\nisso n\xe3o pode corrigir um item."],"comoResolver":["Publique a corre\xe7\xe3o pelo item: consulte os itens previstos do processo, escolha o item\\ncorrigido e envie a errata ou a retifica\xe7\xe3o do ato por ele, informando a publica\xe7\xe3o corrigida\\ne o motivo. Se o documento avulso n\xe3o era uma corre\xe7\xe3o, retire o ato corrigido e o motivo da\\nrequisi\xe7\xe3o e publique-o como aviso ou comunicado."],"ondeAparece":["Publica\xe7\xe3o de documento avulso do processo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Ato do processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);